package org.credivel.config;import java.util.Map;import org.credivel.news.NewsNotFoundException;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class ApiExceptionHandler{@ExceptionHandler(NewsNotFoundException.class)ResponseEntity<Map<String,String>> missing(){return ResponseEntity.status(404).body(Map.of("message","Notícia não encontrada."));}@ExceptionHandler({MethodArgumentNotValidException.class,IllegalArgumentException.class})ResponseEntity<Map<String,String>> invalid(){return ResponseEntity.badRequest().body(Map.of("message","Dados inválidos."));}@ExceptionHandler(Exception.class)ResponseEntity<Map<String,String>> error(){return ResponseEntity.status(500).body(Map.of("message","Não foi possível concluir o pedido."));}}
